        for (evicted_reference, evicted_bytes) in evicted {
            eprintln!(
                "PIC_VIEWER source_cache action=evict bytes={} uri={}",
                evicted_bytes,
                trace_reference(&evicted_reference),
            );
        }
    }
    Ok(ViewerSourceRead {
        bytes,
        cache_hit: false,
